`bench-count-json.mjs` (count runs only):

```js
// Gateway preload: counts JSON.parse calls and parsed characters on this thread, split at 4 KB.
const counts = { calls: 0, chars: 0, bigCalls: 0, bigChars: 0 };
globalThis.__benchJsonCounts = counts;
const parse = JSON.parse;
JSON.parse = function (text, reviver) {
  const length = typeof text === "string" ? text.length : 0;
  counts.calls += 1;
  counts.chars += length;
  if (length >= 4096) {
    counts.bigCalls += 1;
    counts.bigChars += length;
  }
  return parse(text, reviver);
};
```

`bench-observer.mjs` (all runs; it follows the bench's published `$SQLMEASURE_OUT/phase` file):

```js
// Gateway preload for scripts/bench-channel-turn.mts: follows the bench's published
// $SQLMEASURE_OUT/phase file and records, per phase, process CPU (main thread only; it covers
// every thread of the process) and, with --import of bench-count-json.mjs first, JSON.parse
// calls on this thread. Writes $SQLMEASURE_OUT/observer.<pid>.<thread>.json on every change.
import fs from "node:fs";
import path from "node:path";
import { isMainThread, threadId } from "node:worker_threads";

const out = process.env.SQLMEASURE_OUT;
if (out) {
  const file = path.join(out, `observer.${process.pid}.${threadId}.json`);
  const phases = [];
  let current;
  const snapshot = () => {
    const cpu = isMainThread ? process.cpuUsage() : undefined;
    return {
      cpuUs: cpu ? cpu.user + cpu.system : undefined,
      json: globalThis.__benchJsonCounts ? { ...globalThis.__benchJsonCounts } : undefined,
    };
  };
  const flush = () => {
    try {
      fs.writeFileSync(`${file}.new`, JSON.stringify({ pid: process.pid, threadId, isMainThread, phases }));
      fs.renameSync(`${file}.new`, file);
    } catch {}
  };
  const poll = () => {
    let phase;
    try {
      phase = fs.readFileSync(path.join(out, "phase"), "utf8").trim();
    } catch {
      return;
    }
    if (phase === current?.phase) {
      return;
    }
    const now = snapshot();
    if (current) {
      current.end = now;
    }
    current = { phase, start: now };
    phases.push(current);
    flush();
  };
  setInterval(poll, 20).unref();
  process.on("exit", () => {
    if (current) {
      current.end = snapshot();
    }
    flush();
  });
}
```

Timing runs used `OPENCLAW_CHANNEL_BENCH_NODE_OPTIONS="--import <guard> --import bench-observer.mjs"`; count runs added `--import bench-count-json.mjs` before the observer. Per turn, CPU is the Gateway process's `process.cpuUsage()` delta over the turn's phase, and the counts sum all threads.

